bool rck(int ci, int cj) { return ci >= 0 && cj >= 0 && ci < 5 && cj < 5; }

bool is_linked() {
  memset(visit, 0, sizeof(visit));
  int fnct = 0, ci, cj;
  for0(i, 5) for0(j, 5) if(dmm[i][j]) { ci = i; cj = j; break; }
  queue<pii> q; q.push({ ci, cj });
