    auto p = q.front(); q.pop();
    if(visit[p.pf][p.ps]) continue;
    visit[p.pf][p.ps] = true;
    fnct++;
    for0(k, 4) {
      int ai = p.pf + di[k], aj = p.ps + dj[k];
      if(!rck(ai, aj) || !dmm[ai][aj]) continue;
      q.push({ai, aj});
    }
  }
  return fnct == cnt;
}

void dfs(int i, int move) {
