    for0(cj, 5) {
      if(dmm[ci][cj]) continue;
      dmm[ci][cj] = 1;
      dfs(i+1, move + abs(pv[i].pf - ci)+abs(pv[i].ps-cj));
      dmm[ci][cj] = 0;
    }
  }
}

