void fft(vector<complex>& X, cpx w) {
  int len = X.size();
  if(len == 1) return;
  vector<complex> even(len >> 1), odd(len >> 1);
  for(int i = 0; i < len; i++) {
    if(i & 1) odd[i >> 1] = X[i];
    else even[i >> 1] = X[i];
  }
  fft(even, w*w);
  fft(odd, w*w);
  //ceof = 1 + 0i; 
  complex coef(1, 0);
  for(int i = 0; i < len/2; i++) {
    X[i] = even[i] + coef * odd[i];
    X[i + len/2] = even[i] - coef * odd[i];
    coef *= w;
  }
}

void fft(vector<complex> &a) {
  int n = a.size();
  vector<complex> w(n/2), aux(n);
  for(int i=0; i<n/2; i++){
    int k = i&-i;
    if(i == k){
      double ang = 2 * M_PI * i / n;
      // w[i] = cos(ang) + i*sin(ans)
      w[i] = complex(cos(ang), sin(ang)); 
    }
    else w[i] = w[i-k] * w[k];
  }
  for(int i=n/2; i; i>>=1){
    aux = a;
    for(int k=0; 2*k<n; k+=i){
      for(int j=0; j<i; j++){
        cpx u = aux[2*k + j], v = aux[2*k + j + i] * w[k];
        a[k + j] = u + v;
        a[k + j + n/2] = u - v;
      }
    }
  }
}
